// Generated by scripts/build-home-assets.ts --stills and --export with assets.json, its JSON twin
// (docs/LANDING.md 2.6, 2.8, 4.1, 6.1); never edited by hand. Day 0 stub: the integrator wrote the
// types on day 0 (docs/gslides-parity/landing/build/integrator.md "Landing, day 0", section 6);
// L1's push 1 writes the list. assets.test.ts checks every file under public/home/ against it.

export type HomeAppearance = 'light' | 'dark';

/** What a file under public/home/ is (integrator.md section 6, with Kevin's answer 1). */
export type HomeAssetRole =
  /** slide 6's dithered picture (the Rosetta Stone) as a two colour lossless WebP, at most 24 KB */
  | 'canvas-still'
  /** the Rosetta Stone's tone map, a 640 by 360 grey JPEG, at most 26 KB, one for both appearances */
  | 'canvas-tone'
  /** slide 7's dithered picture (the opener field), requested only by the show and the print */
  | 'field-still'
  /** slide 7's picture part from the Perfect file, at most 60 KB */
  | 'export-perfect'
  /** the Editable text file's picture part for slide 7, at most 32 KB */
  | 'export-editable'
  /** the page deck's PDF, 8 pages, requested only on the click of Download the PDF */
  | 'pdf';

export type HomeAsset = {
  role: HomeAssetRole;
  /** null for a file both appearances share (the tone map) */
  appearance: HomeAppearance | null;
  /** the served path, content hashed: /home/<name>-<hash>.<ext> */
  path: string;
  bytes: number;
  sha256: string;
  width: number | null;
  height: number | null;
  /** sha256 of the decoded pixels (RGBA, row major); null for a PDF */
  pixelsSha256: string | null;
  /** an export picture: sha256 of the part inside the file it was read from */
  partSha256: string | null;
  /** a PDF's page count */
  pages: number | null;
};

export const HOME_ASSETS: readonly HomeAsset[] = [];

/** The file of a role in an appearance; throws when the build has not written it. */
export function homeAsset(role: HomeAssetRole, appearance: HomeAppearance | null): HomeAsset {
  const found = HOME_ASSETS.find(
    (asset) =>
      asset.role === role && (asset.appearance === null || asset.appearance === appearance),
  );
  if (found === undefined) throw new RangeError(`no /home asset for ${role} (${appearance})`);
  return found;
}
